INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(14163, 'plPL', 'Wezwanie do boju: Wyspa Podboju', 'W miarę jak zbliżamy się do zwycięstwa w Lodowej Koronie, coraz wyraźniej widać, że nasze armie będą musiały rozprawić się z Hordą, zanim zajmą się Królem Liszem.$B$BElitarna gwardia zwana Kor\'kronem została wysłana, by zablokować nasz pochód na Wyspie Podboju. Wyspa ma kluczowe znaczenie strategiczne, $N. Dopilnuj, żeby nasi chłopcy zwyciężyli!', 'Wygraj bitwę na Wyspie Podboju i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo na Wyspie Podboju', 'Wróć do generała brygady Przymierza.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(14163, 'plPL', 'Horda nigdy nie dorówna naszym siłom, dopóki mamy po swojej stronie ludzi takich jak ty, $N.', 0),
(14164, 'plPL', 'Nic nie stanie między nami a całkowitym zwycięstwem. Za Hordę!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(14163, 'plPL', 'Dobrze cię widzieć, $n! Masz wieści z frontu?', 0),
(14164, 'plPL', 'Czy Przymierze zostało przepędzone z pola bitwy?', 0);
